const msg = $input.first().json;
const chatId = msg.message?.chat?.id || msg.message?.from?.id;
const text = (msg.message?.text || '').trim();
const firstName = msg.message?.from?.first_name || 'друг';
const isVoice = !!msg.message?.voice;
const fileId = msg.message?.voice?.file_id || '';
return [{ json: { chatId, text, firstName, isVoice, fileId } }];

// Объединяем транскрибированный текст с данными из парсинга
const transcribed = $input.first().json.text || '';
const parsed = $('Парсинг сообщения').first().json;
return [{ json: { ...parsed, text: transcribed } }];

// Каталог букетов (обновляй здесь при изменении товаров)
const catalog = [
  {
    name: 'Букет № 1',
    price: 10900,
    composition: 'гортензия, роза пионовидная, гиперикум, подсолнухи, хризантема кустовая',
    recipient: 'любимой',
    photo: 'https://static.tildacdn.com/stor6633-3839-4036-b337-386265376133/139406c440195411c7fbf501652ef9b1.jpg'
  },
  {
    name: 'Букет № 2',
    price: 9181,
    composition: 'роза пионовидная, гиацинт, статица, хризантема кустовая, брассика, бовардия',
    recipient: 'маме',
    photo: 'https://static.tildacdn.com/stor6366-3038-4563-b034-356431346163/d4b8438312daa6a72b4853bb3ce26891.jpg'
  },
  {
    name: 'Букет № 3',
    price: 10340,
    composition: 'роза пионовидная',
    recipient: 'мужчине',
    photo: 'https://static.tildacdn.com/stor3165-6137-4937-a635-393363343637/c7a682531d4e475456748a0745ead9e6.jpg'
  },
  {
    name: 'Букет № 4',
    price: 10980,
    composition: 'гортензия, тюльпан, роза пионовидная, анемон, роза кустовая',
    recipient: 'ребёнку',
    photo: 'https://static.tildacdn.com/stor3937-3733-4631-b238-386633623735/2f46f0ba3b40f2a0a5114bfb1b9fb139.jpg'
  },
  {
    name: 'Букет № 5',
    price: 15580,
    composition: 'тюльпан',
    recipient: 'коллеге',
    photo: 'https://static.tildacdn.com/stor3432-6332-4638-a466-653233656135/ba9cc9276f7bb071d3f1f5099c2b23e8.jpg'
  },
  {
    name: 'Букет № 6',
    price: 12290,
    composition: 'роза пионовидная, хлопок, роза кустовая, гиперикум, тюльпан, астильба, анемон',
    recipient: 'все',
    photo: 'https://static.tildacdn.com/stor3435-3939-4339-b931-613535653532/278d2b32c47c5a7a16f545627544774c.jpg'
  }
];

// Парсим параметры от AI
let params = {};
try {
  const raw = $input.first().json.query || '{}';
  params = JSON.parse(raw);
} catch(e) {
  params = {};
}

const recipient = (params.recipient || '').toLowerCase().trim();
const flowers = (params.flowers || '').toLowerCase().trim();
const budget = parseInt(String(params.budget || '0').replace(/[\s\u00a0]/g, '')) || 0;

// Фильтрация
const results = catalog.filter(item => {
  // Бюджет
  if (budget > 0 && item.price > budget) return false;

  // Адресат (букет №6 подходит всем)
  if (recipient && item.recipient !== 'все') {
    if (!item.recipient.includes(recipient) && !recipient.includes(item.recipient)) return false;
  }

  // Цветы
  if (flowers && flowers !== 'без разницы' && flowers !== 'любые' && flowers !== 'нет') {
    const flowerList = flowers.split(/[,\s]+/).filter(f => f.length > 2);
    const hasFlower = flowerList.some(f => item.composition.toLowerCase().includes(f));
    if (!hasFlower) return false;
  }

  return true;
});

if (results.length === 0) {
  return [{ json: { result: 'Подходящих букетов не найдено. Попробуй убрать ограничение по цветам или увеличить бюджет.' } }];
}

const formatted = results.slice(0, 3).map(item =>
  `🌸 ${item.name} — ${item.price.toLocaleString('ru-RU')} ₽\nСостав: ${item.composition}\nФото: ${item.photo}`
).join('\n\n');

return [{ json: { result: formatted } }];

const agentOutput = $input.first().json.output || '';
const chatId = $('Парсинг сообщения').first().json.chatId;

const orderMatch = agentOutput.match(/##ЗАКАЗ##(.+?)##/);

if (orderMatch) {
  const parts = orderMatch[1].split('|');
  const order = {
    hasOrder: true,
    clientName: parts[0] || '',
    phone: parts[1] || '',
    product: parts[2] || '',
    price: parts[3] || '',
    deliveryType: parts[4] || '',
    address: parts[5] || '',
    date: parts[6] || '',
    time: parts[7] || '',
    chatId
  };
  const cleanText = agentOutput.replace(/##ЗАКАЗ##.+?##/, '').trim();
  return [{ json: { ...order, responseText: cleanText } }];
}

return [{ json: { hasOrder: false, chatId, responseText: agentOutput } }];
